function luhn(s) {
  let sum = 0, double = false;
  for (let i = s.length - 1; i >= 0; i--) {
    let d = +s[i];
    if (double) { d *= 2; if (d > 9) d -= 9; }
    sum += d; double = !double;
  }
  return sum % 10 === 0;
}

